INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64278221', 64278221, 'analyze_legacy', 'Provinsi Kalimantan Selatan', 'provinsi', 'DINAS PERUMAHAN RAKYAT DAN KAWASAN PERMUKIMAN', 'Belanja Jasa Tenaga Ahli - Konsultan Individual', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Kalimantan Selatan, Banjar Baru (Kota)', 41250000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Uraian Tugas Konsultan Individual Pendataan Bidang Perumahan: 1. Melakukan persiapan pelaksanaan pekerjaan melalui koordinasi dengan tim teknis dan pihak terkait serta penyusunan rencana kerja dan metodologi. 2. Mengumpulkan, memutakhirkan, dan mengelola data bidang perumahan, meliputi data backlog perumahan, RTLH, dan data pendukung lainnya. 3. Melakukan analisis backlog kepemilikan dan hunian perumahan serta mengidentifikasi faktor penyebab dan rekomendasi penanganannya. 4. Mengidentifikasi, memverifikasi, dan menganalisis data Rumah Tidak Layak Huni (RTLH) di seluruh kabupaten/kota. 5. Mengintegrasikan data perumahan dari berbagai sumber pendataan (provinsi, kabupaten/kota, pusat, dan instansi terkait). 6. Menganalisis data untuk mendukung perumusan dan penyesuaian kebijakan perumahan daerah agar selaras dengan kebijakan nasional. 7. Menyusun dan meningkatkan sistem pengelolaan data perumahan yang terstandar, akurat, dan berkelanjutan. 8. Melakukan analisis data capaian Standar Pelayanan Minimal (SPM) Bidang Perumahan sebagai bahan evaluasi kinerja. 9. Menyusun laporan berkala serta rekomendasi berbasis data untuk mendukung pengambilan keputusan berbasis bukti.', 'Konsultan Individual Pendataan Bidang Perumahan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1451458);
