INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64317466', 64317466, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Evaluasi dan Penyusunan Laporan Kegiatan Partisipasi Pemerintah RI Pada Expo 2025 Osaka dengan Pembiayaan APBN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 57000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1) Formulasi Metodologi Evaluasi Kinerja: Menyusun kerangka kerja (framework) dan rencana evaluasi yang komprehensif untuk mengukur efektivitas penggunaan APBN dalam partisipasi World Expo 2025 Osaka, mencakup parameter input, output, dan outcome. 2) Audit Operasional dan Manajemen Pelaksanaan: Mengevaluasi dinamika pelaksanaan operasional Paviliun Indonesia selama berlangsungnya Expo, termasuk manajemen arus pengunjung, diplomasi publik, dan efektivitas kegiatan sampingan (side events) dalam mencapai indikator kinerja utama. 3) Analisis Varian dan Efisiensi Anggaran: Melakukan analisis mendalam terhadap kesenjangan (gap analysis) antara perencanaan (DIPA) dan realisasi lapangan, baik dari aspek teknis operasional maupun optimalisasi pembiayaan negara.', '4) Sintesis Lintas Sektoral dan Manajemen Pemangku Kepentingan: Mengintegrasikan data dari berbagai unit teknis internal Bappenas dan instansi terkait untuk menyusun narasi evaluasi yang koheren, guna memastikan laporan memiliki perspektif kebijakan yang utuh. 5) Penyusunan Rekomendasi Strategis dan Laporan Akuntabilitas: Mengonstruksi draf laporan akhir yang tidak hanya bersifat administratif, tetapi juga memuat analisis lesson learned dan rekomendasi kebijakan untuk model partisipasi internasional Indonesia di masa depan. 6) Melaksanakan tugas lainnya yang relevan dengan evaluasi dan pelaporan berdasarkan arahan PPK seperti membantu menyusun bahan pimpinan sesuai permintaan dan kebutuhan. 7) Menyusun laporan pekerjaan sesuai termin yang telah ditentukan selama masa kontrak berlangsung yang berisi rangkuman kegiatan dan dukungan yang diberikan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1452050);
