INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64317344', 64317344, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengelolaan Data dan Informasi Kegiatan Partisipasi Pemerintah RI pada Expo 2025 Osaka', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 63000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1) Membantu PPK dalam mengorganisir dan mengkoordinasikan kebutuhan data dalam mendukung penyusunan rencana monitoring dan evaluasi partisipasi Pemerintah Indonesia pada World Expo 2025 Osaka. 2) Membantu PPK dalam melakukan pengumpulan, verifikasi, dan analisis data pelaksanaan kegiatan partisipasi Pemerintah Indonesia pada World Expo 2025 Osaka. 3) Membantu PPK dalam melakukan pengarsipan asset digital, menyelamatkan konten kreatif, dokumentasi visual, dan data teknis konstruksi pembangunan agar bisa digunakan kembali sebagai referensi untuk pameran internasional di masa depan. 4) Membantu PPK dalam melaksanakan evaluasi data berkala atas progres dan capaian kegiatan partisipasi Pemerintah Indonesia pada World Expo 2025 Osaka. 5) Mendukung laporan evaluasi berkala dan laporan akhir pelaksanaan/monev partisipasi Pemerintah Indonesia pada World Expo 2025 Osaka.', '6) Menyusun data dan informasi bahan pimpinan sesuai permintaan dan kebutuhan. 7) Melakukan koordinasi intensif dengan unit teknis di internal Bappenas dan pihak terkait. 8) Melaksanakan tugas lainnya yang relevan dengan evaluasi dan pelaporan berdasarkan arahan PPK. 9) Menyusun laporan pekerjaan pada akhir masa kontrak yang memuat rangkuman kegiatan dan dukungan yang diberikan selama periode penugasan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1453130);
