INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64317393', 64317393, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Tenaga Ahli Bidang Project Management Sekretariat Paviliun Indonesia pada Expo 2025 Osaka', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 74700000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1) Menyusun rencana kerja pendampingan Tenaga Ahli dalam mendukung kegiatan pascapenyelenggaraan Expo 2025 Osaka sesuai kebutuhan. 2) Membantu PPK dalam menyusun jadwal, mempersiapkan, dan melaksanakan rapat koordinasi rutin dengan penyedia jasa, komite expo, dan/atau pihak terkait lainnya guna memastikan penyelesaian pekerjaan pascapenyelenggaraan dan/atau dismantling berjalan sesuai target. 3) Membantu PPK dalam menyusun jadwal, mempersiapkan, serta mendukung pelaksanaan kegiatan monitoring penyelesaian pekerjaan pascapenyelenggaraan dan/atau dismantling agar proses monitoring berjalan tertib, lancar, dan akuntabel. 4) Membantu PPK dalam melaksanakan koordinasi dengan penyedia jasa, komite expo, dan pihak terkait lainnya sesuai arahan PPK untuk memastikan kelancaran penyelesaian pekerjaan pascapenyelenggaraan dan/atau dismantling.', '5) Membantu PPK dalam mempersiapkan bahan/materi rapat/pertemuan/kegiatan, mengorganisir pelaksanaan rapat/pertemuan/kegiatan, serta menyusun catatan/risalah rapat sesuai kebutuhan. 6) Membantu PPK dalam melakukan koordinasi dengan pihak terkait untuk pembahasan isu, perkembangan pelaksanaan, serta tindak lanjut yang diperlukan pada tahap persiapan, pelaksanaan, maupun pertanggungjawaban pekerjaan pascapenyelenggaraan Expo dan/atau dismantling Paviliun Indonesia. 7) Membantu PPK dalam melakukan pemantauan terhadap kesesuaian capaian dan kinerja penyedia jasa serta menyampaikan catatan atas isu penting yang memerlukan tindak lanjut PPK. 8) Membantu PPK dalam melakukan pengecekan kelengkapan dokumen pertanggungjawaban penyelesaian pekerjaan pascapenyelenggaraan dan/atau dismantling yang disampaikan oleh penyedia jasa, sesuai arahan PPK. 9) Membantu PPK dalam mengidentifikasi potensi hambatan atau risiko manajerial dari sisi pemilik pekerjaan dalam mendukung proses pascapenyelenggaraan untuk dimintakan arahan dan tindak lanjut kepada PPK dan/atau pimpinan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1453776);
